import java.util.Scanner;
import java.util.InputMismatchException;
import java.util.ArrayList;

public class Main {

    public static void main(String[] args) {
        Scanner teclado = new Scanner(System.in);
        Registro registro = new Registro();
        // Carga del comienzo (pedida en el documento)
        registro.registrarIntegracion(new IntegracionFinanciera("API001", "PagoCard", 120, true, "Servicio de tarjetas", "Tarjeta de credito"));
        registro.registrarIntegracion(new IntegracionFinanciera("API002", "BancoDigital", 85, true, "Servicio bancario", "Transferencia bancaria"));
        registro.registrarIntegracion(new IntegracionFinanciera("API003", "WalletGo", 95, true, "Servicio de billetera digital", "Billetera digital"));
        registro.registrarIntegracion(new IntegracionFinanciera("API004", "TransferPlus", 110, false, "Servicio de transferencias", "Transferencia bancaria"));
        registro.registrarIntegracion(new ProveedorLogistica("API005", "EnviosGT", 70, true, "Servicio de envios", 10.0f));
        registro.registrarIntegracion(new ProveedorLogistica("API006", "PaqueteExpress", 95, true, "Servicio de paqueteria", 15.0f));
        registro.registrarIntegracion(new LogisticaAvanzada("API007", "EntregaRapida", 60, true, "Servicio de ultima milla", 8.0f));
        registro.registrarIntegracion(new LogisticaAvanzada("API008", "LogisticaPlus", 110, false, "Servicio logistico avanzado", 12.0f));
        registro.registrarIntegracion(new CertificadorFEL("API009", "FacturaGT", 80, true, "Certificacion de facturas electronicas"));
        registro.registrarIntegracion(new CertificadorFEL("API010", "CertificaPlus", 120, true, "Servicio de certificacion FEL"));


        // Menú

        boolean continuar = true;

        while (continuar) {
            System.out.println("\nSISTEMA DE INTEGRACIONES API\n");
            System.out.println("1. Mostrar integraciones activas");
            System.out.println("2. Buscar integracion por ID");
            System.out.println("3. Ordenar catalogo por latencia");
            System.out.println("4. Consultar estado de conexion");
            System.out.println("5. Cotizar servicio");
            System.out.println("6. Realizar cobro");
            System.out.println("7. Realizar reintegro");
            System.out.println("8. Generar documento");
            System.out.println("9. Registrar evento");
            System.out.println("10. Consultar historial de eventos");
            System.out.println("11. Salir");

            int opcion = 0;
            boolean opcionValida = false;

            // Opción válida
            while (!opcionValida) {

                try {
                    System.out.print("\nSeleccione una opcion: ");
                    opcion = teclado.nextInt();
                    teclado.nextLine();
                    if (opcion >= 1 && opcion <= 11) {
                        opcionValida = true;
                    }
                    else {
                        System.out.println("Seleccione una opcion entre 1 y 11.");
                    }

                } catch (InputMismatchException e) {
                    System.out.println("Entrada invalida. Ingrese un numero.");
                    teclado.nextLine();
                }
            }


            switch (opcion) {
                // Integracioes activas
                case 1: {
                    registro.mostrarIntegraciones();
                    break;
                }
                // Buscar Integraciones
                case 2: {
                    System.out.println("\nBuscar Integracion\n");
                    System.out.print("Ingrese el Id: ");
                    String id = teclado.nextLine();
                    registro.mostrarConfiguracion(id);
                    break;
                }

                // Ordenar por latencia
                case 3: {
                    registro.ordenarIntegraciones();
                    break;
                }

                // Consulte estado
                case 4: {
                    System.out.println("\nConsultar estado\n");
                    System.out.print("Ingrese el Id: ");
                    String id = teclado.nextLine();
                    Integracion integracion = registro.buscarIntegracion(id);
                    if (integracion == null) {
                        System.out.println("No se encontro la integracion.");
                    }
                    else if (integracion instanceof Consultable) {
                        Consultable servicio = (Consultable) integracion;
                        System.out.println("Estado: " + servicio.consultarEstado() );
                    }
                    else {
                        System.out.println("Esta integracion no permite consultar su estado.");
                    }

                    break;
                }


                // Cotización de Servicios
                case 5: {
                    System.out.println("\nCOTIZAR SERVICIO\n");
                    System.out.print("Ingrese el Id: ");
                    String id = teclado.nextLine();
                    Integracion integracion = registro.buscarIntegracion(id);
                    if (integracion == null) {
                        System.out.println("No se encontro la integracion.");
                        break;
                    }
                    if (!integracion.getListo()) {
                        System.out.println("La integracion no esta disponible.");
                        break;
                    }
                    if (!(integracion instanceof Cotizable)) {
                        System.out.println("Esta integracion no permite cotizaciones.");
                        break;
                    }


                    float valor = 0;
                    boolean valorValido = false;

                    while (!valorValido) {

                        try {
                            System.out.print("Ingrese el valor base del servicio: Q");

                            valor = teclado.nextFloat();
                            teclado.nextLine();
                            if (valor > 0 && !Float.isNaN(valor) && !Float.isInfinite(valor)) {
                                valorValido = true;
                            }
                            else {
                                System.out.println("Ingrese un valor positivo.");
                            }

                        } catch (InputMismatchException e) {
                            System.out.println("Entrada invalida.");
                            teclado.nextLine();
                        }
                    }


                    Cotizable servicio = (Cotizable) integracion;
                    float cotizacion = servicio.cotizar(valor);
                    if (cotizacion >= 0) {
                        System.out.printf("Cotizacion: Q%.2f%n", cotizacion);
                    }
                    else {
                        System.out.println("No se pudo realizar la cotizacion.");
                    }

                    break;
                }


                // Realizar cobro
                case 6: {
                    System.out.println("\nREALIZAR COBRO\n");
                    System.out.print("Ingrese el ID: ");
                    String id = teclado.nextLine();
                    Integracion integracion = registro.buscarIntegracion(id);
                    if (integracion == null) {
                        System.out.println("No se encontro la integracion.");
                        break;
                    }
                    if (!(integracion instanceof Cobrable)) {
                        System.out.println("Esta integracion no permite cobros.");
                        break;
                    }
                    if (!integracion.getListo()) {
                        System.out.println("La integracion no esta disponible.");
                        break;
                    }


                    float monto = 0;
                    boolean montoValido = false;

                    while (!montoValido) {

                        try {
                            System.out.print("Monto a cobrar: Q");
                            monto = teclado.nextFloat();
                            teclado.nextLine();
                            if (monto > 0 && !Float.isNaN(monto) && !Float.isInfinite(monto)) {
                                montoValido = true;
                            }
                            else {
                                System.out.println("El monto debe ser positivo.");
                            }

                        } catch (InputMismatchException e) {
                            System.out.println("Entrada invalida.");
                            teclado.nextLine();
                        }
                    }


                    Cobrable servicio = (Cobrable) integracion;
                    if (servicio.cobrar(monto)) {
                        System.out.println("Cobro realizado correctamente.");
                    }
                    else {
                        System.out.println("No se pudo realizar el cobro.");
                    }

                    break;
                }


                // Realizar reintegro
                case 7: {
                    System.out.println("\nREALIZAR REINTEGRO\n");
                    System.out.print("Ingrese el ID: ");
                    String id = teclado.nextLine();
                    Integracion integracion = registro.buscarIntegracion(id);
                    if (integracion == null) {
                        System.out.println("No se encontro la integracion.");
                        break;
                    }
                    if (!(integracion instanceof Reintegrable)) {
                        System.out.println("Esta integracion no permite reintegros.");
                        break;
                    }
                    if (!integracion.getListo()) {
                        System.out.println("La integracion no esta disponible.");
                        break;
                    }


                    float monto = 0;
                    boolean montoValido = false;

                    while (!montoValido) {
                        try {
                            System.out.print("Monto a reintegrar: Q");
                            monto = teclado.nextFloat();
                            teclado.nextLine();
                            if (monto > 0 && !Float.isNaN(monto) && !Float.isInfinite(monto)) {
                                montoValido = true;
                            }
                            else {
                                System.out.println("El monto debe ser positivo.");
                            }

                        } catch (InputMismatchException e) {
                            System.out.println("Entrada invalida.");
                            teclado.nextLine();
                        }
                    }
                    Reintegrable servicio = (Reintegrable) integracion;
                    if (servicio.reintegrar(monto)) {
                        System.out.println("Reintegro realizado correctamente.");
                    }
                    else {
                        System.out.println("No se pudo realizar el reintegro.");
                    }

                    break;
                }

                // Generar documento
                case 8: {
                    System.out.println("\nGENERAR DOCUMENTO\n");
                    System.out.print("Ingrese el ID: ");
                    String id = teclado.nextLine();
                    Integracion integracion = registro.buscarIntegracion(id);
                    if (integracion == null) {
                        System.out.println("No se encontro la integracion.");
                        break;
                    }
                    if (!(integracion instanceof Documentable)) {
                        System.out.println("Esta integracion no genera documentos.");
                        break;
                    }
                    if (!integracion.getListo()) {
                        System.out.println("La integracion no esta disponible.");
                        break;
                    }


                    String datos = "";

                    while (datos.isEmpty()) {
                        System.out.print("Ingrese los datos del documento: ");

                        datos = teclado.nextLine();
                        if (datos.isEmpty()) {
                            System.out.println("Los datos no pueden estar vacios.");
                        }
                    }
                    Documentable servicio = (Documentable) integracion;
                    System.out.println( servicio.generarDocumento(datos) );

                    break;
                }


                // Registrar evento
                case 9: {
                    System.out.println("\nREGISTRAR EVENTO\n");
                    System.out.print("Ingrese el ID: ");
                    String id = teclado.nextLine();
                    Integracion integracion = registro.buscarIntegracion(id);
                    if (integracion == null) {
                        System.out.println("No se encontro la integracion.");
                        break;
                    }
                    if (!(integracion instanceof Auditable)) {
                        System.out.println("Esta integracion no permite auditoria.");
                        break;
                    }
                    if (!integracion.getListo()) {
                        System.out.println("La integracion no esta disponible.");
                        break;
                    }
                    System.out.print("Tipo de evento: ");
                    String tipo = teclado.nextLine();
                    System.out.print("Descripcion del evento: ");
                    String descripcion = teclado.nextLine();


                    int resultado = 0;
                    boolean resultadoValido = false;

                    while (!resultadoValido) {

                        try {
                            System.out.println("1. Exitoso");
                            System.out.println("2. Fallido");
                            System.out.print("Seleccione el resultado: ");

                            resultado = teclado.nextInt();
                            teclado.nextLine();
                            if (resultado == 1 || resultado == 2) {
                                resultadoValido = true;
                            }
                            else {
                                System.out.println("Seleccione 1 o 2.");
                            }

                        } catch (InputMismatchException e) {
                            System.out.println("Entrada invalida.");
                            teclado.nextLine();
                        }
                    }


                    boolean exitoso = false;
                    if (resultado == 1) {
                        exitoso = true;
                    }
                    Evento evento = new Evento( descripcion, tipo, exitoso );

                    Auditable servicio = (Auditable) integracion;

                    servicio.registrarEvento(evento);
                    System.out.println("Evento registrado correctamente.");

                    break;
                }


                // Consultar historial de eventos
                case 10: {
                    System.out.println("\nHISTORIAL DE EVENTOS\n");
                    System.out.print("Ingrese el ID: ");
                    String id = teclado.nextLine();
                    Integracion integracion = registro.buscarIntegracion(id);
                    if (integracion == null) {
                        System.out.println("No se encontro la integracion.");
                        break;
                    }
                    if (!(integracion instanceof Auditable)) {
                        System.out.println("Esta integracion no tiene auditoria.");
                        break;
                    }


                    Auditable servicio = (Auditable) integracion;
                    ArrayList<Evento> historial = servicio.consultarHistorialEventos();
                    if (historial.isEmpty()) {
                        System.out.println("No hay eventos registrados.");
                    }
                    else {

                        for (Evento evento : historial) {
                            System.out.println(evento);
                            System.out.println();
                        }
                    }

                    break;
                }


                // Salir
                case 11: {
                    System.out.println("Saliendo del sistema de integraciones...");

                    continuar = false;
                    break;
                }
            }
        }

        teclado.close();
    }
}
